<img alt="Valentina" class="w-full h-full object-cover" src="https://lh3.googleusercontent.com/aida/AEtjO1U1_yOKCdZz3pfPLUZV6WDF9_3nkaxx3ma0ALmTg6cIyTjBM4hoYG83Z18CpteuzarQGyHigCxnpLDHNOahpG2Lnv7JZJigp13tTpgRJHaesTRJCrM88YKlGtzuS6ro3Mh_kpFOatFNM3fEX5drFG--ML4ALXVHeQOnoZCjobFti09f4qIgIRfO3NbCcyxags881zOPCpig6KvJ-TnyongC2MSp8DH2Rb-lIo9dSxBrgfvH45WChlhIZaEs"/>
</div>
<div>
<h4 class="font-headline text-base font-semibold text-on-surface">Mensaje al Taller de Valentina</h4>
<span class="text-[11px] font-label text-emerald-800 flex items-center gap-1">
<span class="w-1.5 h-1.5 rounded-full bg-emerald-600"></span> Suele responder en menos de 4 horas
            </span>
</div>
</div>
<button class="text-on-surface-variant hover:text-on-surface p-1" onclick="closeInquiryModal()">
<span class="material-symbols-outlined">close</span>
</button>
</div>
<form class="space-y-4" onsubmit="handleInquirySubmit(event)">
<div>
<label class="block text-xs font-label font-medium text-on-surface mb-1">Tu nombre o estudio</label>
<input class="w-full px-3.5 py-2.5 text-xs font-body rounded-xl bg-surface-container-low border-0 text-on-surface placeholder:text-outline focus:ring-2 focus:ring-primary/40" placeholder="Ej. Camila Valenzuela" required="" type="text"/>
</div>
<div>
<label class="block text-xs font-label font-medium text-on-surface mb-1">Correo para recibir la respuesta</label>
<input class="w-full px-3.5 py-2.5 text-xs font-body rounded-xl bg-surface-container-low border-0 text-on-surface placeholder:text-outline focus:ring-2 focus:ring-primary/40" placeholder="tu-correo@ejemplo.com" required="" type="email"/>
</div>
<div>
<label class="block text-xs font-label font-medium text-on-surface mb-1">Tu consulta (dudas sobre piezas, encargos o guías técnicas)</label>
<textarea class="w-full px-3.5 py-2.5 text-xs font-body rounded-xl bg-surface-container-low border-0 text-on-surface placeholder:text-outline focus:ring-2 focus:ring-primary/40" placeholder="Hola Valentina, me gustaría saber si la Jarra Escultórica tolera líquidos calientes..." required="" rows="4"></textarea>
</div>
<div class="flex items-center justify-end gap-3 pt-2">
<button class="px-4 py-2 rounded-xl text-xs font-label font-medium text-on-surface-variant hover:text-on-surface" onclick="closeInquiryModal()" type="button">Cancelar</button>
<button class="px-5 py-2.5 rounded-xl bg-primary text-on-primary hover:bg-primary-container text-xs font-label font-semibold shadow-sm" type="submit">Enviar mensaje directo</button>
</div>
</form>
</div>
</div>
<!-- TOAST FEEDBACK NOTIFICATION -->
<div class="fixed bottom-6 right-6 z-50 transform translate-y-24 opacity-0 transition-all duration-300 pointer-events-none px-4 py-3 rounded-xl bg-inverse-surface text-inverse-on-surface text-xs font-label shadow-xl flex items-center gap-2" id="toast">
<span class="material-symbols-outlined text-emerald-400 text-base" id="toast-icon">check_circle</span>
<span id="toast-msg">Acción completada con éxito</span>
</div>
</div>
<script>
  let isFollowing = false;
  let currentCategory = 'all';

  function showToast(msg, icon = 'check_circle') {
    const toast = document.getElementById('toast');
    const toastMsg = document.getElementById('toast-msg');
    const toastIcon = document.getElementById('toast-icon');
    
    toastMsg.innerText = msg;
    toastIcon.innerText = icon;
    toast.classList.remove('translate-y-24', 'opacity-0');
    toast.classList.add('translate-y-0', 'opacity-100');

    setTimeout(() => {
      toast.classList.remove('translate-y-0', 'opacity-100');
      toast.classList.add('translate-y-24', 'opacity-0');
    }, 3200);
  }

  function toggleFollow() {
    isFollowing = !isFollowing;
    const btn = document.getElementById('follow-btn');
    const text = document.getElementById('follow-text');
    const icon = document.getElementById('follow-icon');

    if (isFollowing) {
      text.innerText = 'Siguiendo Stand #48';
      icon.innerText = 'favorite';
      btn.classList.remove('from-primary', 'to-primary-container');
      btn.classList.add('bg-surface-container-high', 'text-on-surface');
      showToast('Ahora sigues a Taller Barro Mestizo. Recibirás avisos de nuevas hornadas.');
    } else {
      text.innerText = 'Seguir este Stand';
      icon.innerText = 'notifications';
      btn.classList.add('from-primary', 'to-primary-container');
      btn.classList.remove('bg-surface-container-high', 'text-on-surface');
      showToast('Has dejado de seguir el stand.', 'notifications_off');
    }
  }

  function copyStandUrl() {
    navigator.clipboard.writeText(window.location.href);
    showToast('Enlace directo del stand copiado al portapapeles');
  }

  function openInquiryModal() {
    document.getElementById('inquiry-modal').classList.remove('hidden');
  }

  function closeInquiryModal() {
    document.getElementById('inquiry-modal').classList.add('hidden');
  }

  function handleInquirySubmit(e) {
    e.preventDefault();
    closeInquiryModal();
    showToast('Tu mensaje fue enviado a Valentina. Recibirás respuesta por email.');
  }

  function subscribeToKilnAlert() {
    const btn = document.getElementById('kiln-alert-btn');
    btn.innerHTML = `<span class="material-symbols-outlined text-base">check</span> ¡Suscrito para la próxima quema!`;
    btn.classList.add('bg-emerald-700');
    showToast('¡Listo! Te avisaremos al correo cuando salgan las piezas del horno.');
  }

  function switchCategory(category, element) {
    currentCategory = category;

    // Update active tab styling
    document.querySelectorAll('.filter-tab').forEach(tab => {
      tab.classList.remove('bg-primary', 'text-on-primary', 'shadow-sm');
      tab.classList.add('bg-surface-container-lowest', 'text-on-surface');
    });

    if (element) {
      element.classList.remove('bg-surface-container-lowest', 'text-on-surface');
      element.classList.add('bg-primary', 'text-on-primary', 'shadow-sm');
    }

    applySortAndFilter();
  }

  function handleSearch(term) {
    applySortAndFilter();
  }

  function applySortAndFilter() {
    const grid = document.getElementById('product-grid');
    const emptyState = document.getElementById('empty-state-view');
    const counter = document.getElementById('inventory-counter');
    const searchTerm = document.getElementById('stand-search').value.toLowerCase().trim();
    const priceFilter = document.getElementById('price-filter').value;
    const sortFilter = document.getElementById('sort-filter').value;
    const items = Array.from(document.querySelectorAll('.product-item'));

    if (currentCategory === 'custom-order') {
      grid.classList.add('hidden');
      emptyState.classList.remove('hidden');
      counter.innerHTML = 'Mostrando <strong class="text-on-surface font-semibold">0 creaciones</strong> disponibles en esta categoría';
      return;
    }

    grid.classList.remove('hidden');
    emptyState.classList.add('hidden');

    let visibleCount = 0;

    items.forEach(card => {
      const cardCategory = card.getAttribute('data-category') || '';
      const cardPrice = parseInt(card.getAttribute('data-price') || '0', 10);
      const cardTitle = card.querySelector('h3').innerText.toLowerCase();

      let matchesCategory = (currentCategory === 'all') || cardCategory.includes(currentCategory);
      let matchesSearch = !searchTerm || cardTitle.includes(searchTerm);

      let matchesPrice = true;
      if (priceFilter === 'under15') matchesPrice = cardPrice < 15000;
      else if (priceFilter === '15to30') matchesPrice = cardPrice >= 15000 && cardPrice <= 30000;
      else if (priceFilter === 'over30') matchesPrice = cardPrice > 30000;

      if (matchesCategory && matchesSearch && matchesPrice) {
        card.classList.remove('hidden');
        visibleCount++;
      } else {
        card.classList.add('hidden');
      }
    });

    // Sorting visible cards
    const visibleCards = items.filter(card => !card.classList.contains('hidden'));
    visibleCards.sort((a, b) => {
      const priceA = parseInt(a.getAttribute('data-price'), 10);
      const priceB = parseInt(b.getAttribute('data-price'), 10);
      const popA = parseInt(a.getAttribute('data-popular'), 10);
      const popB = parseInt(b.getAttribute('data-popular'), 10);

      if (sortFilter === 'asc') return priceA - priceB;
      if (sortFilter === 'desc') return priceB - priceA;
      if (sortFilter === 'popular') return popB - popA;
      return 0; // default order
    });

    visibleCards.forEach(card => grid.appendChild(card));

    counter.innerHTML = `Mostrando <strong class="text-on-surface font-semibold">${visibleCount} creaciones</strong> disponibles en el stand`;
  }
</script></main><footer class="w-full bg-surface-container-low border-t border-outline-variant/40 text-on-surface"><div class="max-w-7xl mx-auto px-6 lg:px-12 py-16"><div class="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-12 gap-12 mb-16"><div class="lg:col-span-4 flex flex-col gap-space-md"><div class="flex items-center gap-space-sm"><span class="font-headline font-semibold text-[26px] text-on-surface">Feria Ikigai</span></div><p class="font-body text-[14px] leading-relaxed text-on-surface-variant max-w-sm">Un santuario digital para la artesanía con alma, donde creadores de obras físicas y digitales comparten sus piezas con intención, calma y devoción por el detalle.</p><div class="pt-space-xs"><span class="font-label font-bold text-[11px] uppercase tracking-wider text-primary-container">Edición Virtual Permanente</span></div></div><div class="lg:col-span-2 flex flex-col gap-space-sm"><span class="font-headline font-semibold text-[16px] text-on-surface mb-space-xs">Descubrir</span><a class="font-body text-[14px] text-on-surface-variant hover:text-primary-container transition-colors" data-path="recorrer-feria" href="#">Recorrer Feria</a><a class="font-body text-[14px] text-on-surface-variant hover:text-primary-container transition-colors" data-path="stands-y-tiendas" href="#">Stands y Tiendas</a><a class="font-body text-[14px] text-on-surface-variant hover:text-primary-container transition-colors" data-path="categorias" href="#">Categorías</a><a class="font-body text-[14px] text-on-surface-variant hover:text-primary-container transition-colors" data-path="historias-de-creadores" href="#">Historias de Creadores</a></div><div class="lg:col-span-2 flex flex-col gap-space-sm"><span class="font-headline font-semibold text-[16px] text-on-surface mb-space-xs">Para Creadores</span><a class="font-body text-[14px] text-on-surface-variant hover:text-primary-container transition-colors" data-path="abrir-mi-stand" href="#">Abrir mi Stand</a><a class="font-body text-[14px] text-on-surface-variant hover:text-primary-container transition-colors" data-path="manifiesto" href="#">Manifiesto</a><a class="font-body text-[14px] text-on-surface-variant hover:text-primary-container transition-colors" data-path="sostenibilidad" href="#">Sostenibilidad</a><a class="font-body text-[14px] text-on-surface-variant hover:text-primary-container transition-colors" data-path="ayuda-y-contacto" href="#">Ayuda &amp; Contacto</a></div><div class="lg:col-span-4 flex flex-col gap-space-md"><span class="font-headline font-semibold text-[20px] text-on-surface">Drops del Fin de Semana</span><p class="font-body text-[13px] text-on-surface-variant leading-relaxed">Suscríbete a nuestra carta quincenal para recibir lanzamientos exclusivos de talleres artesanos y colecciones digitales de autor.</p><form class="flex items-center gap-space-xs w-full" onsubmit="event.preventDefault();"><input class="flex-1 px-space-md py-space-sm rounded-lg bg-surface-container-lowest border border-outline-variant/50 text-on-surface font-body text-[13px] placeholder:text-outline focus:outline-none focus:ring-1 focus:ring-primary-container" placeholder="tu-correo@estudio.com" type="email"/><button class="px-space-md py-space-sm rounded-lg bg-primary-container hover:bg-primary text-on-primary font-body font-semibold text-[14px] transition-colors" type="submit">Unirme</button></form><span class="font-label text-[11px] text-outline">Sin spam. Solo historias y oficios selectos.</span></div></div><div class="pt-8 border-t border-outline-variant/30 flex flex-col sm:flex-row items-center justify-between gap-space-md text-on-surface-variant font-body text-[13px]"><div class="flex items-center gap-space-lg"><a class="hover:text-primary-container transition-colors" data-path="manifiesto" href="#">Manifiesto</a><a class="hover:text-primary-container transition-colors" data-path="sostenibilidad" href="#">Sostenibilidad</a><a class="hover:text-primary-container transition-colors" data-path="ayuda-y-contac